entries[190817] = { ["name"] = "Schattengeschoss", ["text"] = "100 Meter Reichweite\nWirken in 1 sek.\nDer Zaubernde schleudert Blitze aus Schattenenergie auf zufällige Stellen in der Umgebung. Gegner, die davon getroffen werden, erleiden Schattenschaden.\nJeder Einschlag erzeugt eine Schattenzone, die allen Spielercharakteren, die die Zone betreten, Schattenschaden zufügt." }
